import { AlreadyArchivedError } from "@/lib/soft-delete";
import * as orgService from "@/server/services/organization-service";
import * as sessionService from "@/server/services/session-service";
import * as invitationService from "@/server/services/invitation-service";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import { runTrialExpiryJob } from "@/server/jobs/trial-expiry-job";
import { toErr } from "./x";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());

describe("close", () => {
  it("works", async () => {
    const t = await createTenant("closeme", "growth");
    const other = await createTenant("keepme", "growth");
    await memberRepo.insertMember(other.org.id, t.userIds.member, "member", null);
    await usageRepo.recomputeUsage(t.org.id);
    const inv = await invitationService.inviteMember(t.actors.admin, { orgId: t.org.id, email: "x@y.test", role: "member" });
    expect(inv).toBeTruthy();
    await expect(orgService.deleteOrganization(t.actors.owner, { orgId: t.org.id, confirmSlug: "wrong" })).rejects.toThrow();
    expect((await orgRepo.findOrgById(t.org.id))?.archivedAt).toBeNull();
    const closed = await orgService.deleteOrganization(t.actors.owner, { orgId: t.org.id, confirmSlug: "closeme" });
    expect(closed.archivedAt).not.toBeNull();
    await expect(orgService.deleteOrganization(t.actors.owner, { orgId: t.org.id, confirmSlug: "closeme" })).rejects.toBeInstanceOf(AlreadyArchivedError);
    expect((await subscriptionRepo.findSubscription(t.org.id))?.status).toBe("canceled");
    expect((await orgService.listOrganizationsForUser(t.userIds.member)).map((o) => o.slug)).toEqual(["keepme"]);
    const actor = await sessionService.resolveActorForOrg({ userId: t.userIds.member, email: "", activeOrgId: t.org.id, expiresAt: "2099-01-01T00:00:00.000Z" } as never, "closeme");
    expect(actor).toBeNull();
    expect(await orgService.resolveOrgBySlug("closeme")).toBeNull();
    expect(await usageRepo.listOrgIdsForRollup(50)).not.toContain(t.org.id);
    const r = await runTrialExpiryJob(new Date("2099-01-01"));
    expect(r.processed).toBeGreaterThan(0);
    expect((await subscriptionRepo.findSubscription(t.org.id))?.status).toBe("canceled");
    const owner2 = await userRepo.insertUser({ email: "o2@z.test", name: "o2", passwordHash: "seed" });
    const created = await orgService.createOrganization(owner2.id, { name: "n", slug: "closeme", plan: "free" } as never);
    expect(created.slug).not.toBe("closeme");
    expect(await sessionService.assertNotAlreadyClosed).toBeUndefined;
    await expect(orgService.assertNotAlreadyClosed(t.userIds.owner, t.org.id)).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(orgService.assertNotAlreadyClosed(t.userIds.member, t.org.id)).resolves.toBeUndefined();
    void toErr;
  });
});
EOF
